import json
with open('/app/resources/treasury_bulletin_1970_12.json', 'r') as f:
    data = json.load(f)

# Find tables in the data
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_tables(v, path + '.' + k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_tables(item, path + f'[{i}]')
    elif isinstance(obj, str):
        if 'PDO-2' in obj or 'Offerings' in obj or 'Treasury Bills' in obj:
            print(f'Found at {path}: {obj[:100]}')

find_tables(data)
